{"status":"candidate","chosen_option":"flow","assumptions":["A minimum-cost flow of two units from the earliest to latest endpoint represents selecting intervals: each time arc has capacity 2 and cost 0, and each interval arc from its start to end has capacity 1 and cost −weight.","Successive shortest augmenting paths with residual edges and shortest-path potentials can be implemented in O(n^2 log n), suitable for n ≤ 2000."],"observations":[{"statement":"Intervals are half-open, so sorted endpoint coordinates with forward arcs allow touching intervals to share a boundary without overlap.","source_ids":["task"]},{"statement":"The empty subset is allowed, so a negative-cost interval-selection objective can return a nonnegative optimum.","source_ids":["task"]}],"artifact":{"code":"import sys
import heapq


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    intervals = [(data[i], data[i + 1], data[i + 2]) for i in range(1, 3 * n + 1, 3)]
    coords = sorted({x for s, e, _ in intervals for x in (s, e)})
    m = len(coords)
    index = {x: i for i, x in enumerate(coords)}
    graph = [[] for _ in range(m)]

    def add_edge(u, v, cap, cost):
        graph[u].append([v, len(graph[v]), cap, cost])
        graph[v].append([u, len(graph[u]) - 1, 0, -cost])

    for i in range(m - 1):
        add_edge(i, i + 1, 2, 0)
    for s, e, w in intervals:
        add_edge(index[s], index[e], 1, -w)

    # Initial potentials are shortest distances in the initial forward DAG.
    inf = 10**30
    potential = [inf] * m
    potential[0] = 0
    for u in range(m):
        if potential[u] == inf:
            continue
        for v, rev, cap, cost in graph[u]:
            if cap and v > u:
                potential[v] = min(potential[v], potential[u] + cost)
    potential = [0 if x == inf else x for x in potential]

    total_cost = 0
    source, sink = 0, m - 1
    for _ in range(2):
        dist = [inf] * m
        prev_node = [-1] * m
        prev_edge = [-1] * m
        dist[source] = 0
        pq = [(0, source)]
        while pq:
            d, u = heapq.heappop(pq)
            if d != dist[u]:
                continue
            for ei, edge in enumerate(graph[u]):
                v, rev, cap, cost = edge
                if cap:
                    nd = d + cost + potential[u] - potential[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        prev_node[v] = u
                        prev_edge[v] = ei
                        heapq.heappush(pq, (nd, v))
        if dist[sink] == inf:
            break
        for v in range(m):
            if dist[v] < inf:
                potential[v] += dist[v]
        add_cost = 0
        v = sink
        while v != source:
            u = prev_node[v]
            ei = prev_edge[v]
            edge = graph[u][ei]
            add_cost += edge[3]
            edge[2] -= 1
            graph[v][edge[1]][2] += 1
            v = u
        total_cost += add_cost

    print(-total_cost)


if __name__ == '__main__':
    main()
